const $=s=>document.querySelector(s);
const fmt=n=>n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const st={q:'',b:'',min:0,con:false,sort:'name',shown:100,sel:new Set()};
const S={date:'',until:'',pn:'KERJETH JEROME D. ABELLA',pt:'LRCO I/BPLO-Designate',tn:'NARISA E. GALZOTE',tt:'Municipal Treasurer'};
try{Object.assign(S,JSON.parse(localStorage.getItem('cdg')||'{}'))}catch(e){}
S.date=new Date().toISOString().slice(0,10);
let cache={};let cur=[];
function base(con){
 if(cache[con])return cache[con];const m=new Map();
 for(const r of D){const k=con?r[1].toUpperCase()+'|'+r[5]:r[2];let g=m.get(k);
  if(!g){g={k,owner:r[1],brgy:r[5],mail:r[4],rows:[],total:0,from:9999};m.set(k,g)}
  g.rows.push(r);g.total+=r[13];g.from=Math.min(g.from,+r[8].slice(0,4)||9999)}
 return cache[con]=[...m.values()]}
function groups(){
 const q=st.q.trim().toUpperCase();
 let a=base(st.con).filter(g=>(!st.b||g.brgy===st.b)&&g.total>=st.min&&(!q||g.owner.toUpperCase().includes(q)||g.rows.some(r=>r[2].includes(q)||r[0].includes(q))));
 if(st.sort==='amt')a.sort((x,y)=>y.total-x.total);
 else if(st.sort==='old')a.sort((x,y)=>x.from-y.from||x.owner.localeCompare(y.owner));
 else a.sort((x,y)=>x.owner.localeCompare(y.owner));
 return a}
function render(){
 cur=groups();const props=cur.reduce((s,g)=>s+g.rows.length,0),tot=cur.reduce((s,g)=>s+g.total,0);
 $('#stats').textContent=`${cur.length.toLocaleString()} ${st.con?'taxpayers':'declarations'}, ${props.toLocaleString()} properties, ₱${fmt(tot)} due`;
 const n=st.sel.size;$('#mk').textContent=n?`Make ${n} selected notice${n>1?'s':''}`:`Make notices for all ${cur.length.toLocaleString()} results`;
 $('#mk').disabled=!cur.length;
 $('#rows').innerHTML=cur.length?cur.slice(0,st.shown).map((g,i)=>`<tr><td><input type="checkbox" data-i="${i}" ${st.sel.has(g.k)?'checked':''} aria-label="Select ${esc(g.owner)}"></td><td>${esc(g.owner)}${g.rows.length>1?`<span class="tag">${g.rows.length} TDs</span>`:''}</td><td>${esc(g.brgy)}</td><td>${esc(g.rows[0][2])}</td><td>${esc(g.rows[0][3]||'—')}</td><td>${g.from<9999?g.from:'—'}</td><td class="r amt">₱${fmt(g.total)}</td><td><button class="sm" data-n="${i}">Notice</button></td></tr>`).join(''):`<tr><td colspan="8" class="empty">No one matches. Try a shorter name or clear the barangay filter.</td></tr>`;
 $('#more').innerHTML=cur.length>st.shown?`<button id="sm">Show more (${(cur.length-st.shown).toLocaleString()} left)</button>`:'';
 $('#all').checked=cur.length>0&&cur.every(g=>st.sel.has(g.k))}
const W1=['','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'],W2=['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
function w(n){if(n<20)return W1[n];if(n<100)return W2[n/10|0]+(n%10?'-'+W1[n%10]:'');if(n<1000)return W1[n/100|0]+' hundred'+(n%100?' '+w(n%100):'');
 for(const[v,s]of[[1e9,'billion'],[1e6,'million'],[1e3,'thousand']])if(n>=v)return w(n/v|0)+' '+s+(n%v?' '+w(n%v):'')}
function words(x){const p=Math.floor(x),c=Math.round((x-p)*100);return((p?w(p):'zero')+' pesos').replace(/(^|[ -])([a-z])/g,(m,a,b)=>a+b.toUpperCase())+' and '+String(c).padStart(2,'0')+'/100'}
const SEAL1='data:image/jpeg;base64,',SEAL2='data:image/jpeg;base64,';
const tc=s=>s.toLowerCase().replace(/(^|[ .(-])([a-z])/g,(m,a,b)=>a+b.toUpperCase());
function nat(n){const p=n.split(',');return p.length===2&&p[1].trim()&&!/[&;]|\bAND\b|\bHRS\b|\bSPS\b|\bET\b/i.test(n)?p[1].trim()+' '+p[0].trim():n}
function notice(g){
 const r=g.rows[0],x=r[0],td=(/^\d\d-\d{4}-/.test(r[2])?r[2].slice(0,3)+'06-'+r[2].slice(3):r[2])+'/'+x.slice(5,9)+'-'+x.slice(9,12)+'-'+x.slice(12,14)+'-'+x.slice(14,18);
 const dt=new Date(S.date+'T00:00:00').toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
 return `<section class="sheet" contenteditable="true" spellcheck="false"><div class="mt">MTO-001-0</div>
<div class="hd"><img src="${SEAL1}" alt=""><div class="ht">Republic of the Philippines<br>Province of Ilocos Norte<br><b>MUNICIPALITY OF CURRIMAO</b></div><img src="${SEAL2}" alt=""></div>
<div class="of">OFFICE OF THE MUNICIPAL TREASURER</div>
<div class="dt"><span>${dt}</span>Date</div>
<div class="ad"><b>${esc(nat(g.owner))}</b><i>${esc(tc(g.brgy))}, Currimao, Ilocos Norte</i></div>
<p>Dear Sir/Ma’am:</p>
<p class="ind">Records show that you have real property tax delinquency on your property computed as follows:</p>
<dl class="pr"><dt>Declared Owner/s:</dt><dd>${esc(g.owner)}</dd><dt>Tax Declaration No.:</dt><dd>${esc(td)}</dd><dt>Lot No.:</dt><dd>${esc([...new Set(g.rows.map(row=>String(row[3]||'').trim()).filter(Boolean))].join(', ')||'—')}</dd><dt>Location of Property:</dt><dd>${esc(g.brgy)}</dd><dt>Classification:</dt><dd>${esc(r[6])}</dd><dt>Assessed Value:</dt><dd>${r[7]?fmt(r[7]):''}</dd></dl>
<table class="t"><thead><tr><th class="x"></th><th colspan="2">BASIC</th><th colspan="2">SEF</th><th class="x"></th></tr><tr><th>TAX YEAR</th><th>TAX</th><th>PENALTY</th><th>TAX</th><th>PENALTY</th><th>TOTAL AMOUNT</th></tr></thead><tbody><tr><td>${esc(r[8])}</td>${[9,10,11,12,13].map(i=>`<td>₱${fmt(r[i])}</td>`).join('')}</tr></tbody></table>
<div class="tt">Total Tax Due ----- <b>Php</b><span>${fmt(r[13])}</span></div>
<p class="nt"><i>Please settle the delinquency immediately to avoid additional penalties.</i><br><b class="rd">Computation is good until ${esc(S.until.toUpperCase())||'______________'}. DISREGARD IF PAID.</b></p>
<div class="sg"><div>Prepared by:<b>${esc(S.pn)}</b><i>${esc(S.pt)}</i></div><div>Very truly yours,<b>${esc(S.tn)}</b><i>${esc(S.tt)}</i></div></div>
<div class="rc">Received by: <span></span><small>Printed Name Over Signature &amp; Date</small></div></section>`}
function make(list){if(!list.length)return;const cap=list.slice(0,300);
 $('#notices').innerHTML=cap.map(notice).join('');
 $('#pvn').textContent=list.length>300?`Showing the first 300 of ${list.length.toLocaleString()}. Filter by barangay to print the rest.`:`${list.length.toLocaleString()} notice${list.length>1?'s':''}`;
 document.body.classList.add('pv');scrollTo(0,0)}
function save(){try{localStorage.setItem('cdg',JSON.stringify({until:S.until,pn:S.pn,pt:S.pt,tn:S.tn,tt:S.tt}))}catch(e){}}
// wiring
function fillB(){const v=st.b;$('#b').innerHTML='<option value="">All barangays</option>'+[...new Set(D.map(r=>r[5]))].sort().map(b=>`<option>${esc(b)}</option>`).join('');$('#b').value=v}
fillB();
const BUILT=D;
function hk(s){return String(s==null?'':s).toUpperCase().replace(/[^A-Z0-9]/g,'')}
function parse(wb){
 const a=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,raw:true,defval:''});
 const hi=a.findIndex(r=>r.some(c=>hk(c)==='XPIN'));if(hi<0)throw new Error('No header row with an XPIN column was found.');
 const H=a[hi].map(hk),col=(aliases,d)=>{
  // Prefer exact header matches, then common extended labels; ignore blank headers.
  let i=H.findIndex(h=>h && aliases.includes(h));
  if(i<0)i=H.findIndex(h=>h && aliases.some(alias=>h.startsWith(alias)));
  if(i<0)i=H.findIndex(h=>h && aliases.some(alias=>alias.length>=5 && h.includes(alias)));
  return i<0?d:i
 };
 const c={x:col(['XPIN'],0),o:col(['OWNERNAME','OWNER'],1),td:col(['TDNUMBER','TDNO','TAXDECLARATIONNUMBER','TAXDECLARATIONNO'],2),lot:col(['LOTNO','LOTNUMBER','LOTNUM','LOTNUMBERNO','LOT'],3),m:col(['MAILINGADDRESS','MAILINGADDRESSS'],4),b:col(['BARANGAY'],5),cl:col(['CLASSIFICATION'],6),av:col(['ASSESSEDVALUE'],7),y:col(['TAXYEAR'],8),bt:col(['BASICTAX'],9),bp:col(['BASICPENALTY'],10),st:col(['SEFTAX'],12),sp:col(['SEFPENALTY'],13),t:col(['TOTALAMOUNTDUE','TOTAL'],15)};
 const cl=s=>String(s==null?'':s).replace(/\s+/g,' ').trim(),nm=v=>{v=parseFloat(String(v).replace(/,/g,''));return isFinite(v)?Math.round(v*100)/100:0};
 const canon=b=>cl(b).toUpperCase().replace(/\s*LOT\s*(NO\.?)?\s*\d+$/,'').trim().replace('SALLINDEG','SALINDEG').replace('PAGULUDAN SALINDEG','PAGULUDAN-SALINDEG').replace('STA CRUZ','STA. CRUZ');
 const rows=a.slice(hi+1).filter(r=>cl(r[c.x])&&cl(r[c.td])),cnt={};
 rows.forEach(r=>{const b=cl(r[c.b]),k=cl(r[c.td]).split('-')[1];if(b){cnt[k]=cnt[k]||{};const n=canon(b);cnt[k][n]=(cnt[k][n]||0)+1}});
 const by=k=>cnt[k]?Object.entries(cnt[k]).sort((p,q)=>q[1]-p[1])[0][0]:'';
 return rows.map(r=>{const td=cl(r[c.td]),br=cl(r[c.b])?canon(r[c.b]):by(td.split('-')[1]),bt=nm(r[c.bt]),bp=nm(r[c.bp]),s=nm(r[c.st]),sp=nm(r[c.sp]),t=nm(r[c.t]);
  return [String(r[c.x]).replace(/\D/g,'').padStart(18,'0'),cl(r[c.o]),td,cl(r[c.lot]),cl(r[c.m])||br,br,cl(r[c.cl]),nm(r[c.av]),cl(r[c.y]),bt,bp,s,sp,t||Math.round((bt+bp+s+sp)*100)/100]})}
const on=(id,ev,f)=>$(id).addEventListener(ev,f);
on('#q','input',e=>{st.q=e.target.value;st.shown=100;render()});
on('#b','change',e=>{st.b=e.target.value;st.shown=100;render()});
on('#min','input',e=>{st.min=+e.target.value||0;st.shown=100;render()});
on('#sort','change',e=>{st.sort=e.target.value;render()});
on('#clr','click',()=>{st.sel.clear();render()});
on('#all','change',e=>{cur.forEach(g=>e.target.checked?st.sel.add(g.k):st.sel.delete(g.k));render()});
on('#mk','click',()=>make(st.sel.size?cur.filter(g=>st.sel.has(g.k)):cur));
on('#rows','click',e=>{const t=e.target;
 if(t.dataset.n!==undefined)make([cur[+t.dataset.n]]);
 else if(t.dataset.i!==undefined){const k=cur[+t.dataset.i].k;t.checked?st.sel.add(k):st.sel.delete(k);render()}});
on('#more','click',e=>{if(e.target.id==='sm'){st.shown+=200;render()}});
on('#back','click',()=>document.body.classList.remove('pv'));
on('#print','click',()=>{try{window.print()}catch(e){}});
on('#pr','click',async()=>{
 const area=$('#notices');
 const sheets=[...area.querySelectorAll('.sheet')];
 if(!sheets.length){alert('Please generate at least one notice first.');return}
 if(typeof html2pdf==='undefined'){
  alert('The PDF exporter could not load. Check your internet connection, then try again. You can still use Print and choose “Save as PDF” in the print dialog.');
  return;
 }
 const first=sheets[0].querySelector('.ad b')?.textContent||'Delinquency_Notices';
 const safe=first.replace(/[^a-z0-9_-]+/gi,'_').replace(/^_+|_+$/g,'')||'Delinquency_Notices';
 const opt={margin:0,filename:`${safe}_Notices.pdf`,image:{type:'jpeg',quality:0.95},
  html2canvas:{scale:2,useCORS:true,backgroundColor:'#ffffff',scrollX:0,scrollY:-window.scrollY},
  jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}};
 const btn=$('#pr');btn.disabled=true;const label=btn.textContent;
 try{
  let pdf=null;
  for(let i=0;i<sheets.length;i++){
   btn.textContent=`Saving PDF… ${i+1}/${sheets.length}`;
   // render ONE notice per canvas so the canvas never exceeds browser size limits
   const canvas=await html2pdf().set(opt).from(sheets[i]).toCanvas().get('canvas');
   const fresh=!pdf;
   if(fresh)pdf=await html2pdf().set(opt).from(canvas).toPdf().get('pdf');
   const pw=210,ph=297,m=10,maxW=pw-2*m,maxH=ph-2*m;
   let w=maxW,h=canvas.height*w/canvas.width;
   if(h>maxH){h=maxH;w=canvas.width*h/canvas.height}
   pdf.addPage();
   if(fresh)pdf.deletePage(1); // drop the placeholder page html2pdf made while creating the PDF
   pdf.addImage(canvas.toDataURL('image/jpeg',0.95),'JPEG',(pw-w)/2,m,w,h);
   canvas.width=canvas.height=0;
   await new Promise(r=>setTimeout(r));
  }
  pdf.save(opt.filename);
 }
 catch(err){console.error(err);alert('Could not create the PDF. Try the Print button and select “Save as PDF”.')}
 finally{btn.disabled=false;btn.textContent=label}
});
on('#word','click',()=>{
 const sheets=[...document.querySelectorAll('#notices .sheet')];
 if(!sheets.length){alert('Please generate at least one notice first.');return}
 const css=`
 @page{size:A4;margin:16mm}body{font-family:Arial,sans-serif;color:#000;font-size:11pt}
 .sheet{width:100%;padding:0;margin:0 auto;page-break-after:always;font:11pt/1.35 Arial,sans-serif;color:#000}
 .sheet:last-child{page-break-after:auto}.sheet p{margin:0 0 8px}.sheet .ind{text-indent:10mm}
 .sheet .mt{text-align:right;font-weight:bold}.sheet .hd{display:flex;justify-content:center;align-items:center;gap:22px}
 .sheet .hd img{width:24mm;height:24mm;object-fit:contain}.sheet .ht{text-align:center;line-height:1.3}
 .sheet .of{text-align:center;font-weight:bold;font-size:12.5pt;margin:4px 0 14px}
 .sheet .dt{width:36mm;margin:0 0 12px auto;text-align:center}.sheet .dt span{display:block;border-bottom:1px solid #000}
 .sheet .ad{width:90mm;margin-bottom:10px;border-bottom:1px solid #000}.sheet .ad b,.sheet .ad i{display:block}
 .sheet .pr{display:table;width:100%;margin:8px 0 12px}.sheet .pr dt{display:table-cell;width:44mm;padding:1px 0}
 .sheet .pr dd{display:table-cell;margin:0;font-weight:bold;border-bottom:1px solid #000;padding:1px 0;min-height:1.35em}
 .sheet table.t{border-collapse:collapse;width:100%;text-align:center;font-size:10.5pt}.sheet .t th,.sheet .t td{border:1px solid #000;padding:1px 4px}.sheet .t th.x{border:0}
 .sheet .tt{text-align:right;margin:10px 0 8px}.sheet .tt span{display:inline-block;min-width:34mm;border:1px solid #000;text-align:right;font-weight:bold;padding:0 6px;margin-left:12px}
 .sheet .nt{margin:10px 0 0 10mm}.sheet .rd{color:#e00000}.sheet .sg{display:table;width:100%;margin-top:14px}
 .sheet .sg>div{display:table-cell;width:50%;vertical-align:top}.sheet .sg b,.sheet .sg i{display:block;text-align:center}.sheet .sg b{margin-top:34px}
 .sheet .rc{margin-top:26px}.sheet .rc span{display:inline-block;width:70mm;border-bottom:1px solid #000}.sheet .rc small{display:block;margin-left:22mm;width:70mm;text-align:center;font-size:11pt}`;
 const content=sheets.map(el=>el.outerHTML).join('\n');
 const doc=`<!doctype html><html><head><meta charset="utf-8"><style>${css}</style></head><body>${content}</body></html>`;
 const blob=new Blob(['\ufeff',doc],{type:'application/msword;charset=utf-8'});
 const url=URL.createObjectURL(blob),a=document.createElement('a');
 const first=sheets[0].querySelector('.ad b')?.textContent||'Delinquency_Notices';
 const safe=first.replace(/[^a-z0-9_-]+/gi,'_').replace(/^_+|_+$/g,'')||'Delinquency_Notices';
 a.href=url;a.download=`${safe}_Notices.doc`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
});
[['#s-date','date'],['#s-until','until'],['#s-pn','pn'],['#s-pt','pt'],['#s-tn','tn'],['#s-tt','tt']].forEach(([id,k])=>{
 $(id).value=S[k];on(id,'input',e=>{S[k]=e.target.value;save()})});
render();
on('#imp','change',async e=>{const f=e.target.files[0];if(!f)return;$('#err').textContent='';
 try{if(typeof XLSX==='undefined')throw new Error('The Excel reader did not load. Check your connection and try again.');
  const rows=parse(XLSX.read(await f.arrayBuffer(),{type:'array'}));
  if(!rows.length)throw new Error('No rows with both an XPIN and a TD number were found.');
  D=rows;cache={};st.sel.clear();st.b='';st.shown=100;fillB();$('#src').textContent=`${f.name}: ${rows.length.toLocaleString()} records`;$('#rst').hidden=false;render();
 }catch(x){$('#err').textContent='Could not import: '+x.message}
 e.target.value=''});
